#include <iostream>
#include <cstdio>
#include <cstring>
#include <vector>
#include <algorithm>
#include <cmath>

using namespace std;

using int64 = long long;
constexpr int MAX_SIZE = 66;

int R, C, TOTAL, idx;
char INPUT[MAX_SIZE];
int64 COMB[MAX_SIZE][MAX_SIZE];

int countA[MAX_SIZE], countB[MAX_SIZE];
vector<int64> PARTIAL[MAX_SIZE], PARTIAL_ZERO[MAX_SIZE];

void precompute_comb() {
    for (int i = 0; i <= TOTAL; ++i) {
        COMB[i][0] = 1;
        for (int j = 1; j <= i; ++j)
            COMB[i][j] = COMB[i-1][j-1] + COMB[i-1][j];
    }
}

int64 compute_delta(int pattern, int a_before, int b_before) {
    int64 result = 0;
    int64 temp1, temp2;

    for (int k = 0; k < C + 1; ++k) {
        if (pattern & (1 << k)) {
            ++b_before;
            temp1 = COMB[b_before - 1][R - 1];
            temp2 = COMB[TOTAL - b_before][R] - COMB[a_before][R];
            result -= temp1 * temp2;
        } else {
            ++a_before;
            temp1 = COMB[a_before - 1][R - 1];
            temp2 = COMB[TOTAL - a_before][R] - COMB[b_before][R];
            result += temp1 * temp2;
        }
    }
    return result;
}

bool is_valid_pattern(int pattern) {
    for (int k = 0; k < C + 1; ++k) {
        if (INPUT[2 * R + C + k] == 'A' && ((pattern >> k) & 1) == 1) return false;
        if (INPUT[2 * R + C + k] == 'B' && ((pattern >> k) & 1) == 0) return false;
    }
    return true;
}

void construct_tables() {
    int max_pattern = 1 << (C + 1);

    for (int pat = 0; pat < max_pattern; ++pat) {
        int b_here = __builtin_popcount(pat);
        int a_here = C + 1 - b_here;

        if (is_valid_pattern(pat))
            PARTIAL[a_here].push_back(compute_delta(pat, R + C - a_here, R + C - b_here));
        else
            PARTIAL_ZERO[a_here].push_back(compute_delta(pat, R + C - a_here, R + C - b_here));
    }

    for (int k = 0; k <= C + 1; ++k) {
        sort(PARTIAL[k].begin(), PARTIAL[k].end());
        sort(PARTIAL_ZERO[k].begin(), PARTIAL_ZERO[k].end());
    }
}

int64 get_multiplier(int pattern) {
    int i, j;

    for (i = 0; i < C + 1; ++i)
        if (((pattern >> i) & 1) != (pattern & 1))
            break;

    for (j = i; j < C + 1; ++j) {
        if (INPUT[2 * R - 1 + j] == 'A' && (((pattern >> j) & 1) == 1)) return 0;
        if (INPUT[2 * R - 1 + j] == 'B' && (((pattern >> j) & 1) == 0)) return 0;
    }

    int set_a = R - 1 + ((pattern & 1) == 0 ? i : 0);
    int set_b = R - 1 + ((pattern & 1) == 1 ? i : 0);

    if (set_a < countA[2 * R - 2 + i]) return 0;
    if (set_b < countB[2 * R - 2 + i]) return 0;
    return COMB[set_a + set_b - countA[2 * R - 2 + i] - countB[2 * R - 2 + i]][set_a - countA[2 * R - 2 + i]];
}

void update_optimal(pair<int64, int64>& best, pair<int64, int64> candidate) {
    if (candidate.first < 0) candidate.first = -candidate.first;

    if (best.first < candidate.first) return;
    if (best.first > candidate.first) {
        best = candidate;
        return;
    }
    best.second += candidate.second;
}

int64 count_target(const vector<int64>& arr, int64 target) {
    auto lo = lower_bound(arr.begin(), arr.end(), target);
    auto hi = upper_bound(arr.begin(), arr.end(), target);
    return hi - lo;
}

int64 compute_answer() {
    int max_pattern = 1 << (C + 1);
    pair<int64, int64> best = make_pair(1LL << 60, 0);

    for (int pat = 0; pat < max_pattern; ++pat) {
        int b_here = __builtin_popcount(pat);
        int a_here = C + 1 - b_here;
        int64 current = compute_delta(pat, R - 1, R - 1);

        int64 multiplier = get_multiplier(pat);
        auto iter = lower_bound(PARTIAL[C + 1 - a_here].begin(), PARTIAL[C + 1 - a_here].end(), -current);

        if (iter != PARTIAL[C + 1 - a_here].end()) {
            if (best.first >= abs(*iter + current)) {
                int64 mult2 = count_target(PARTIAL[C + 1 - a_here], *iter);
                update_optimal(best, make_pair(*iter + current, multiplier * mult2));
            }
        }

        if (iter != PARTIAL[C + 1 - a_here].begin()) {
            --iter;
            if (best.first >= abs(*iter + current)) {
                int64 mult2 = count_target(PARTIAL[C + 1 - a_here], *iter);
                update_optimal(best, make_pair(*iter + current, multiplier * mult2));
            }
        }

        multiplier = 0;
        iter = lower_bound(PARTIAL_ZERO[C + 1 - a_here].begin(), PARTIAL_ZERO[C + 1 - a_here].end(), -current);

        if (iter != PARTIAL_ZERO[C + 1 - a_here].end()) {
            int64 mult2 = count_target(PARTIAL_ZERO[C + 1 - a_here], *iter);
            if (best.first >= abs(*iter + current)) {
                update_optimal(best, make_pair(*iter + current, multiplier * mult2));
            }
        }

        if (iter != PARTIAL_ZERO[C + 1 - a_here].begin()) {
            --iter;
            if (best.first >= abs(*iter + current)) {
                int64 mult2 = count_target(PARTIAL_ZERO[C + 1 - a_here], *iter);
                update_optimal(best, make_pair(*iter + current, multiplier * mult2));
            }
        }
    }

    return best.second;
}

int main() {
    scanf("%d%d\n%s", &R, &C, INPUT + 1);
    TOTAL = 2 * (R + C);

    precompute_comb();

    for (idx = 1; idx <= TOTAL; ++idx) {
        countA[idx] = countA[idx - 1] + (INPUT[idx] == 'A' ? 1 : 0);
        countB[idx] = countB[idx - 1] + (INPUT[idx] == 'B' ? 1 : 0);
    }

    construct_tables();
    int64 result = compute_answer();
    printf("%lld", result);

    return 0;
}
